#include "mvt.h"

void kernel_mvt(
    double x1[40],
    double x2[40],
    double y_1[40],
    double y_2[40],
    double A[40][40])
{
    // Compute x1 = x1 + A * y1
    for (int i = 0; i < 40; i++) {
        double sum = x1[i];
        for (int j = 0; j < 40; j++) {
            sum += A[i][j] * y_1[j];
        }
        x1[i] = sum;
    }

    // Compute x2 = x2 + A^T * y2
    for (int i = 0; i < 40; i++) {
        double sum = x2[i];
        for (int j = 0; j < 40; j++) {
            sum += A[j][i] * y_2[j];
        }
        x2[i] = sum;
    }
}
